STORY = [('wen_simo', '网上那些关于惠美的东西你看到了吧？说辛惠美隐婚。', "You've seen everything circulating online about Huimei, right — claiming she is secretly married?", [(63, '网上那些东西你看到了吧'), (64, '关于惠美的'), (66, '辛惠美隐婚')], ''), ('wen_simo', '咱俩都是了解她的，怎么可能会有这种事呢，真是荒谬。', "Both of us know her well; how could anything like that be true? It's utterly absurd.", [(67, '咱俩都是了解她的'), (68, '怎么可能会有这种事呢'), (69, '真是荒谬')], ''), ('wen_simo', '那孩子怎么回事，你知道吗？', 'Do you know what the story is with that child?', [(70, '那孩子怎么回事'), (71, '你知道吗')], ''), ('chun_yuqiao', '我也不知道。其实问过了，但是她拒绝沟通。', "I don't know either. Our team asked, in fact, though she refused to discuss it.", [(72, '我也不知道'), (75, '其实问过了'), (76, '拒绝沟通')], ''), ('chun_yuqiao', '可不管怎样，那个孩子肯定不是她的。她一定有她的理由。', 'Regardless, that child is definitely not hers, and she must have her own reasons for staying silent.', [(77, '可不管怎样'), (78, '那个孩子肯定不是'), (82, '她一定有她的理由')], ''), ('wen_simo', '惠美刚被法国的品牌选为亚洲区的代言人，因为这件事对方要解约了。', 'Huimei was just chosen as regional ambassador for an international brand, and now they want to terminate her contract.', [(83, '惠美刚被法国的品牌'), (84, '选为亚洲区的代言人'), (88, '对方要解约了')], ''), ('wen_simo', '说是惠美损害了他们想要的那种独立女性的形象。', 'They claim she damaged the independent-woman image their brand wants to project.', [(89, '说是惠美损害了'), (90, '想要的那种'), (91, '独立女性的形象')], ''), ('wen_simo', '国际大单被退约，收入损失是小，可如果损害了她的声誉，会对以后的事业造成长远的影响。', 'Losing the fee is minor, whereas lasting damage to her reputation will hurt her entire career.', [(93, '国际大单被退约'), (94, '收入损失是小'), (96, '损害了她的声誉'), (98, '造成长远的影响')], ''), ('chun_yuqiao', '这事我听说了。', 'I already heard about the contract issue.', [(99, '这事我听说了')], ''), ('wen_simo', '我直话直说，你们星天的经纪部太弱了，我希望你能够亲自出马。', "Speaking frankly, Xingtian's talent management unit is far too weak — I hope you will step in personally.", [(100, '我直话直说'), (102, '经纪部太弱了'), (105, '我希望你能够亲自出马')], ''), ('chun_yuqiao', '惠美是我签进星天的，我责无旁贷，你放心。', 'I was the one who brought Huimei to Xingtian; it is my responsibility, so rest assured.', [(106, '惠美是我'), (106, '星天的'), (107, '我责无旁贷 你放心')], ''), ('wen_simo', '一大早来打扰你很不好意思，我走了。', "Sorry to disturb you so early in the morning — I'll head out now.", [(108, '一大早来打扰你'), (109, '很不好意思'), (111, '我走了')], '')]
WALK = [(0, None, '"You\'ve seen everything circulating online about Huimei, right — claiming she is secretly married?"'), (1, None, '"Both of us know her well; how could anything like that be true? It\'s utterly absurd."'), (2, None, "'Do you know what the story is with that child?'"), (3, None, '"I don\'t know either. Our team asked, in fact, though she refused to discuss it."'), (4, None, "'Regardless, that child is definitely not hers, and she must have her own reasons for staying silent.'"), (5, None, "'Huimei was just chosen as regional ambassador for an international brand, and now they want to terminate her contract.'"), (6, None, "'They claim she damaged the independent-woman image their brand wants to project.'"), (7, None, "'Losing the fee is minor, whereas lasting damage to her reputation will hurt her entire career.'"), (8, None, "'I already heard about the contract issue.'"), (9, None, '"Speaking frankly, Xingtian\'s talent management unit is far too weak — I hope you will step in personally."'), (10, None, "'I was the one who brought Huimei to Xingtian; it is my responsibility, so rest assured.'"), (11, None, '"Sorry to disturb you so early in the morning — I\'ll head out now."')]
